#ifndef HTIF_H
#define HTIF_H

#include <stddef.h>
#include <stdint.h>

// L1 Cache Control Commands
#define CCTL_L1D_WBINVAL_ALL 6
#define CCTL_L1D_WB_ALL      7
#define CCTL_L1D_INVAL_ALL   23

// L2 Cache Control and Status Constants
#define CCTL_L2_WBINVAL_ALL  0x12
#define CCTL_L2_ST_RUNNING   1
#define CCTL_ST_MASK         0xF

// L2 Cache Control Register Addresses
#define L2C_REG_CTL          0xe0500008
#define L2C_REG_CCTL         0xe0500040
#define L2C_REG_CCTL_M0_ST   0xe0500080
#define TOHOST_CMD_REG       0xe0080010

#if __riscv_xlen == 64
#define TOHOST_CMD(dev, cmd, payload) \
  (((uint64_t)(dev) << 56) | ((uint64_t)(cmd) << 48) | (uint64_t)(payload))
#define REG_T uint64_t
#else
#define TOHOST_CMD(dev, cmd, payload) \
  ({ \
    if ((dev) || (cmd)) \
      __builtin_trap(); \
    (payload); \
  })
#define REG_T uint32_t
#endif

static inline void flush_all_dcache(void)
{
  // L1 DCache writeback and invalidate all
  asm volatile("csrw mcctlcommand, %0" :: "rK"(CCTL_L1D_WBINVAL_ALL));

#if __riscv_xlen == 64
  // Check for L2 cache and flush it if available
  asm volatile(
    "csrr    t0, mmsc_cfg\n"
    "li      t1, 1\n"
    "slli    t1, t1, 46\n"
    "and     t2, t0, t1\n"
    "beqz    t2, 1f\n"
    "li      t3, 0xe0500008\n"
    "ld      t4, 0(t3)\n"
    "andi    t4, t4, 1\n"
    "beqz    t4, 1f\n"
    "li      t5, 0xe0500040\n"
    "li      t6, %[cmd]\n"
    "sd      t6, 0(t5)\n"
    "2:\n"
    "li      t2, 0xe0500080\n"
    "ld      t3, 0(t2)\n"
    "li      t4, %[mask]\n"
    "and     t3, t3, t4\n"
    "li      t5, %[running]\n"
    "beq     t3, t5, 2b\n"
    "1:\n"
    :
    : [cmd] "K"(CCTL_L2_WBINVAL_ALL),
      [mask] "K"(CCTL_ST_MASK),
      [running] "K"(CCTL_L2_ST_RUNNING)
  );
#endif
}

__attribute__((used)) static inline void sim_syscall(uint64_t dev,
                                                       uint64_t cmd,
                                                       uint64_t tohost)
{
  volatile uint64_t* command = (volatile uint64_t*) TOHOST_CMD_REG;
  uint64_t tohost_cmd = TOHOST_CMD(dev, cmd, tohost);
  flush_all_dcache();
  *command = tohost_cmd;
  asm volatile("fence rw,rw");
}

__attribute__((used)) static inline uint64_t frontend_syscall(uint64_t n,
                                                               uint64_t a0,
                                                               uint64_t a1,
                                                               uint64_t a2,
                                                               uint64_t a3,
                                                               uint64_t a4,
                                                               uint64_t a5,
                                                               uint64_t a6)
{
  volatile uint64_t magicmem[8] = {n, a0, a1, a2, a3, a4, a5, a6};
  sim_syscall(0, 0, (uintptr_t) magicmem);
  return magicmem[0];
}

#endif // HTIF_H
  return SYSCALL_2(5, tp, tzp);
}

__attribute__((used)) int _open(const char* name __attribute__((unused)),
                                   int flags,
                                   int permission,
                                   ...)
{
  return SYSCALL_3(6, name, flags, permission);
}

__attribute__((used)) ssize_t _write(int fd __attribute__((unused)),
                                        const void* ptr,
                                        size_t len)
{
  if (fd > 2) {
    return SYSCALL_3(7, fd, ptr, len);
  }

  volatile uint8_t* display = (volatile uint8_t*) DISPLAY_BASE_ADDR;
  for (size_t i = 0; i < len; ++i)
    *display = *((uint8_t*) ptr + i);
  return len;
}

__attribute__((used)) int _getcwd(const char* name __attribute__((unused)),
                                     int size,
                                     ...)
{
  return SYSCALL_2(8, name, size);
}

__attribute__((used)) ssize_t _lseek(int fd, int offset, int dir)
{
  return SYSCALL_3(9, fd, offset, dir);
}

__attribute__((used)) ssize_t _read(int fd, void* buf, int len)
{
  return SYSCALL_3(10, fd, buf, len);
}
__attribute__((used, noreturn)) void _exit(int exit_status)
{
  volatile uint32_t* command = (volatile uint32_t*) EXIT_COMMAND_ADDR;
  *command = exit_status;
  __asm__ __volatile__("1: j 1b");
  __builtin_unreachable();
}

__attribute__((used)) void* _sbrk(intptr_t increment)
{
  extern char _end[];
  static char* p = _end;
  void* base = p;
  p += increment;
  return base;
}

#ifdef __cplusplus
}
#endif

